// Compiles content/docs/*.md and content/lessons/*.yaml into src/content.generated.ts.
// `--check` fails when the generated file is out of date (used in CI).
import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { ContentError, parseLearningDoc, parseLesson } from '@archguide/core';
import type { LearningDoc, Lesson } from '@archguide/core';
import { CONCEPTS, RELATION_TYPES } from '../src';

const root = fileURLToPath(new URL('..', import.meta.url));
const target = join(root, 'src/content.generated.ts');

function load<T>(dir: string, ext: string, parse: (text: string, source: string) => T): T[] {
  return readdirSync(join(root, dir))
    .filter((f) => f.endsWith(ext))
    .sort()
    .map((f) => parse(readFileSync(join(root, dir, f), 'utf8'), `${dir}/${f}`));
}

let docs: LearningDoc[];
let lessons: Lesson[];
try {
  docs = load('content/docs', '.md', parseLearningDoc);
  lessons = load('content/lessons', '.yaml', parseLesson);
} catch (e) {
  if (!(e instanceof ContentError)) throw e;
  console.error(e.message);
  process.exit(1);
}

for (const doc of docs) {
  if (doc.source !== `content/docs/${doc.id}.md`) {
    console.error(`${doc.source}: the file name must be "${doc.id}.md"`);
    process.exit(1);
  }
}
for (const lesson of lessons) {
  const expected = `content/lessons/${lesson.id.slice('lesson.'.length)}.yaml`;
  if (lesson.source !== expected) {
    console.error(`${lesson.source}: the file name must be "${expected}"`);
    process.exit(1);
  }
}

const text = `// Generated by scripts/build-content.ts from content/. Do not edit. Run: pnpm content
import type { LearningDoc, Lesson } from '@archguide/core';

export const DOCS: LearningDoc[] = ${JSON.stringify(docs, null, 2)};

export const LESSONS: Lesson[] = ${JSON.stringify(lessons, null, 2)};
`;

const ids = new Set(docs.map((d) => d.id));
const coverage = (list: { id: string }[]) =>
  `${list.filter((x) => ids.has(x.id)).length}/${list.length}`;
const summary =
  `${docs.length} docs, ${lessons.length} lessons; ` +
  `concepts with a doc: ${coverage(CONCEPTS)}, profile relation types with a doc: ${coverage(RELATION_TYPES)}`;

if (process.argv.includes('--check')) {
  let current = '';
  try {
    current = readFileSync(target, 'utf8');
  } catch {
    // Missing file counts as out of date.
  }
  if (current !== text) {
    console.error('src/content.generated.ts is out of date. Run: pnpm content');
    process.exit(1);
  }
  console.log(`Content is up to date (${summary}).`);
} else {
  writeFileSync(target, text);
  console.log(`Wrote src/content.generated.ts (${summary}).`);
}
